using namespace std;

int main(){
  int n,m;
  cin >> n >> m;
  vector<int> bk(n+1,0);
  for(int i=0;i<m;i++){
    int a;
    cin >> a;
    bk[a]=1;
  }
  vector<int> res;
  for(int i=1;i<=n;i++){
    if(bk[i]==0){
      res.push_back(i);
    }
  }
  cout << res.size() << "\n";
  for(int i=0;i<res.size();i++){
    if(i){cout << " ";}
    cout << res[i];
  }cout << "\n";
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

int main(){
  int n,m;
  cin >> n >> m;
  vector<int> a(m);
  for(auto &nx : a){cin >> nx;}
  sort(a.begin(),a.end());
  int p=0;
  vector<int> res;
  for(int i=1;i<=n;i++){
    if(p>m){res.push_back(i);}
    else if(a[p]!=i){res.push_back(i);}
    else{p++;}
  }
  cout << res.size() << "\n";
  for(int i=0;i<res.size();i++){
    if(i){cout << " ";}
    cout << res[i];
  }cout << "\n";
  return 0;
}
